// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/**
 * An unpriced incumbent may be refreshed by an unpriced offer of the same physical expression (same operator, child
 * groups and tier) whose child winners each rank at least as well as the incumbent's, at least one strictly better
 * (priced beats unpriced, a lower price beats a higher one). Nothing else may change: an unpriced offer never displaces
 * a priced incumbent, and unpriced offers of different expressions are still not compared by children.
 */
class PackedWinnerTableChildRefreshTest {

	private static final int PARENT = 1;
	private static final int CHILD = 2;
	private static final int SECOND_CHILD = 3;
	private static final int GRANDPARENT = 4;

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void unpricedIncumbentIsRefreshedBySameExpressionOverAStrictlyBetterChild(int tier, int context) {
		PackedWinnerTable winners = table();
		int unpricedChild = unpriced(winners, tier, 0, CHILD, 20, 1.0d);
		int incumbent = unpriced(winners, tier, context, PARENT, 10, 5.0d, unpricedChild);
		int pricedChild = priced(winners, tier, 0, CHILD, 21, 1.0d, 50.0d);
		assertNotEquals(unpricedChild, pricedChild, "fixture: a priced child displaces the unpriced child winner");

		int refreshed = unpriced(winners, tier, context, PARENT, 10, 3.0d, pricedChild);

		assertNotEquals(incumbent, refreshed, "the same expression over a strictly better child refreshes");
		assertEquals(refreshed, winners.find(PARENT, 1, 0, context, 0));
		assertEquals(pricedChild, winners.childWinnerId(refreshed, 0));
		assertTrue(Double.isNaN(winners.totalCost(refreshed)), "a refresh does not invent a price");
		assertEquals(unpricedChild, winners.childWinnerId(incumbent, 0), "earlier winner records remain immutable");
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void lowerPricedChildIsStrictlyBetter(int tier, int context) {
		PackedWinnerTable winners = table();
		int expensiveChild = priced(winners, tier, 0, CHILD, 20, 1.0d, 90.0d);
		int incumbent = unpriced(winners, tier, context, PARENT, 10, 5.0d, expensiveChild);
		int cheaperChild = priced(winners, tier, 0, CHILD, 21, 1.0d, 40.0d);

		int refreshed = unpriced(winners, tier, context, PARENT, 10, 3.0d, cheaperChild);

		assertNotEquals(incumbent, refreshed);
		assertEquals(cheaperChild, winners.childWinnerId(refreshed, 0));
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void equalChildrenDoNotRefresh(int tier, int context) {
		PackedWinnerTable winners = table();
		int child = unpriced(winners, tier, 0, CHILD, 20, 1.0d);
		int incumbent = unpriced(winners, tier, context, PARENT, 10, 5.0d, child);

		assertEquals(incumbent, unpriced(winners, tier, context, PARENT, 10, 3.0d, child),
				"no child is strictly better");
		assertEquals(incumbent, winners.find(PARENT, 1, 0, context, 0));
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void oneBetterAndOneWorseChildDoNotRefresh(int tier, int context) {
		PackedWinnerTable winners = table();
		int expensiveFirst = priced(winners, tier, 0, CHILD, 20, 1.0d, 90.0d);
		int cheapFirst = priced(winners, tier, 0, CHILD, 21, 1.0d, 10.0d);
		int unpricedSecond = unpriced(winners, tier, 0, SECOND_CHILD, 30, 1.0d);
		int pricedSecond = priced(winners, tier, 0, SECOND_CHILD, 31, 1.0d, 50.0d);
		int incumbent = unpriced(winners, tier, context, PARENT, 10, 5.0d, cheapFirst, unpricedSecond);

		assertEquals(incumbent, unpriced(winners, tier, context, PARENT, 10, 3.0d, expensiveFirst, pricedSecond),
				"a worse first child vetoes the better second child");
		assertEquals(incumbent, winners.find(PARENT, 1, 0, context, 0));
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void differentExpressionIsNotComparedByChildren(int tier, int context) {
		PackedWinnerTable winners = table();
		int unpricedChild = unpriced(winners, tier, 0, CHILD, 20, 1.0d);
		int incumbent = unpriced(winners, tier, context, PARENT, 10, 5.0d, unpricedChild);
		int pricedChild = priced(winners, tier, 0, CHILD, 21, 1.0d, 50.0d);

		assertEquals(incumbent, unpriced(winners, tier, context, PARENT, 11, 3.0d, pricedChild),
				"another physical expression stays incomparable without prices");
		assertEquals(incumbent, winners.find(PARENT, 1, 0, context, 0));
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void refreshNeverDowngradesAPricedIncumbent(int tier, int context) {
		PackedWinnerTable winners = table();
		int unpricedChild = unpriced(winners, tier, 0, CHILD, 20, 1.0d);
		int incumbent = priced(winners, tier, context, PARENT, 10, 5.0d, 100.0d, unpricedChild);
		int pricedChild = priced(winners, tier, 0, CHILD, 21, 1.0d, 50.0d);

		assertEquals(incumbent, unpriced(winners, tier, context, PARENT, 10, 3.0d, pricedChild),
				"an unpriced offer never displaces a priced incumbent");
		assertEquals(100.0d, winners.totalCost(winners.find(PARENT, 1, 0, context, 0)));
	}

	@ParameterizedTest
	@CsvSource({ "0,0", "0,7", "1,0", "1,7" })
	void refreshPropagatesThroughUnpricedAncestorsOfTheSameExpression(int tier, int context) {
		PackedWinnerTable winners = table();
		int unpricedChild = unpriced(winners, tier, 0, CHILD, 20, 1.0d);
		int parent = unpriced(winners, tier, 0, PARENT, 10, 5.0d, unpricedChild);
		int grandparent = unpriced(winners, tier, context, GRANDPARENT, 40, 9.0d, parent);
		int pricedChild = priced(winners, tier, 0, CHILD, 21, 1.0d, 50.0d);
		int refreshedParent = unpriced(winners, tier, 0, PARENT, 10, 3.0d, pricedChild);
		assertNotEquals(parent, refreshedParent);

		int refreshedGrandparent = unpriced(winners, tier, context, GRANDPARENT, 40, 7.0d, refreshedParent);

		assertNotEquals(grandparent, refreshedGrandparent,
				"the refreshed parent dominates the old parent through its strictly better child");
		assertEquals(refreshedParent, winners.childWinnerId(refreshedGrandparent, 0));
	}

	private static PackedWinnerTable table() {
		return new PackedWinnerTable(8, 8, 32, 1);
	}

	private static int unpriced(PackedWinnerTable winners, int tier, int context, int group, int physical,
			double startup, int... children) {
		return offer(winners, tier, context, group, physical, startup, Double.NaN, Double.NaN, Double.NaN, children);
	}

	private static int priced(PackedWinnerTable winners, int tier, int context, int group, int physical,
			double startup, double total, int... children) {
		return offer(winners, tier, context, group, physical, startup, total, total, 0.0d, children);
	}

	private static int offer(PackedWinnerTable winners, int tier, int context, int group, int physical,
			double startup, double total, double comparison, double memory, int[] children) {
		return tier == PackedWinnerTable.COSTED
				? winners.offerWithMetadata(group, 1, 0, context, 0, physical, 0, 0, startup, total, comparison,
						memory, false, children, 0, children.length)
				: winners.offerExecutableFallbackWithMetadata(group, 1, 0, context, 0, physical, 0, 0, startup,
						total, comparison, memory, false, children, 0, children.length);
	}
}
